patch_result.patch:
--- a/libsepol/cil/src/cil_binary.c
+++ b/libsepol/cil/src/cil_binary.c
@@ -642,11 +642,27 @@
 	value = sepol_type->s.value;

 	ebitmap_for_each_positive_bit(cil_attr->types, tnode, i) {
+		if (i >= db->num_types || db->val_to_type == NULL || db->val_to_type[i] == NULL) {
+			cil_log(CIL_ERR, "Typeattribute %s has invalid type index %u in type set\n",
+				cil_attr->datum.fqn, i);
+			rc = SEPOL_ERR;
+			goto exit;
+		}
+
 		rc = __cil_get_sepol_type_datum(pdb, DATUM(db->val_to_type[i]), &sepol_type);
 		if (rc != SEPOL_OK) goto exit;
+		if (sepol_type->s.value == 0 || sepol_type->s.value > pdb->p_types.nprim) {
+			cil_log(CIL_ERR, "Typeattribute %s resolved invalid type value %u\n",
+				cil_attr->datum.fqn, sepol_type->s.value);
+			rc = SEPOL_ERR;
+			goto exit;
+		}

-		ebitmap_set_bit(&pdb->type_attr_map[sepol_type->s.value - 1], value - 1, 1);
-		ebitmap_set_bit(&pdb->attr_type_map[value - 1], sepol_type->s.value - 1, 1);
+		if (ebitmap_set_bit(&pdb->type_attr_map[sepol_type->s.value - 1], value - 1, 1) ||
+		    ebitmap_set_bit(&pdb->attr_type_map[value - 1], sepol_type->s.value - 1, 1)) {
+			rc = SEPOL_ERR;
+			goto exit;
+		}
 	}

 	rc = SEPOL_OK;

